export function loadMcpConfig(overridePath?: string): McpConfig {
  let config: McpConfig = { mcpServers: {} };
  for (const source of getConfigSources(overridePath)) {
    const loaded = readValidatedConfig(source.readPath, ...);
    if (!loaded) continue;
    config = mergeConfigs(config, expandImports(loaded));
  }
  return config;
}

export async function initializeMcp(pi: ExtensionAPI, ctx: ExtensionContext): Promise<McpExtensionState> {
  const config = loadMcpConfig(configPath);
  const manager = new McpServerManager();
  const lifecycle = new McpLifecycleManager(manager);
  ...
  for (const [name, definition] of serverEntries) {
    lifecycle.registerServer(name, definition, idleOverride);
  }
}

export async function executeCall(state, toolName, args?, serverOverride?, getPiTools?): Promise<ProxyToolResult> {
  // Find server by name or prefix
  if (!serverName && !toolMeta && prefixMode !== 'none') {
    const candidates = Object.keys(state.config.mcpServers)
      .map(name => ({ name, prefix: getServerPrefix(name, prefixMode) }))
      .filter(c => c.prefix && toolName.startsWith(c.prefix + '_'));
  }
  // Execute tool call
  const resultPromise = connection.client.callTool({
    name: toolMeta.originalName, arguments: args ?? {}, _meta: uiSession?.requestMeta
  });
}

export interface ExtensionAPI {
  on(event: string, handler: ExtensionHandler): void;
  registerTool(tool: ToolDefinition): void;
  registerCommand(name: string, options: RegisteredCommand): void;
  registerShortcut(shortcut: KeyId, options: {...}): void;
  registerFlag(name: string, options: {...}): void;
  getAllTools(): ToolInfo[];
  setActiveTools(toolNames: string[]): void;
  registerProvider(name: string, config: ProviderConfig): void;
}

